// Fragmento del servidor: quién elige la identidad del despacho nuevo
if (m === "POST" && partes.length === 1) {          // POST /despachos
  const id = "D-" + String(proximo++).padStart(4, "0");   // la elige el servidor
  guardar(id, { destino: cuerpo.destino, bultos: cuerpo.bultos, estado: "pendiente" });
  return responder(res, 201, forma(id, despachos.get(id)), { location: `/despachos/${id}` });
}
if (m === "PUT" && partes.length === 2) {           // PUT /despachos/D-0100
  const id = partes[1];                                    // la elige el cliente, está en la URL
  const existia = despachos.has(id);
  guardar(id, { destino: cuerpo.destino, bultos: cuerpo.bultos, estado: cuerpo.estado ?? "pendiente" });
  return responder(res, existia ? 200 : 201, forma(id, despachos.get(id)));
}

// Repetir la misma operación dos veces: ¿queda igual que hacerla una sola vez?
const base = () => ({ despachos: ["D-1"], bultos: 12 });
const operaciones = {
  "PUT: bultos pasa a ser 20":    (s) => { s.bultos = 20; },
  "POST: agregar un despacho":    (s) => { s.despachos.push("D-" + (s.despachos.length + 1)); },
  "PATCH: sumar 1 bulto":         (s) => { s.bultos += 1; },
  "PATCH: estado pasa a en_ruta": (s) => { s.estado = "en_ruta"; },
  "DELETE: sacar D-1":            (s) => { s.despachos = s.despachos.filter((x) => x !== "D-1"); },
};
for (const [nombre, op] of Object.entries(operaciones)) {
  const una = base(); op(una);
  const dos = base(); op(dos); op(dos);
  console.log(nombre.padEnd(30), JSON.stringify(una) === JSON.stringify(dos) ? "mismo resultado" : "resultado distinto");
}
